mapper.select:
select team_id
from group_buy_team_order
where activity_id = #{groupBuyTeamOrderReq.activityId} and user_id != #{groupBuyTeamOrderReq.userId}
  and source = #{groupBuyTeamOrderReq.source} and goods_id = #{groupBuyTeamOrderReq.goodsId}
  and channel = #{groupBuyTeamOrderReq.channel} and end_time > now() and status in (0, 1)
order by id desc
limit #{limitCount}

mapper.update:
update group_buy_team_order
set is_header = 1, update_time = now()
where user_id = #{userId}

update group_buy_team_order
set status = 2, update_time = now()
where user_id = #{userId} and order_id = #{orderId}

update group_buy_team_order
set out_refund_no = #{outRefundNo}, out_refund_no_complete_time = #{outRefundNoCompleteTime}, update_time = now()
where user_id = #{userId} and out_trade_no = #{outTradeNo}
